  "4a": 4,
  "4o": 4,
  "4": 4,
  quinta: 5,
  quinto: 5,
  cinco: 5,
  "5a": 5,
  "5o": 5,
  "5": 5,
  sexta: 6,
  sexto: 6,
  seis: 6,
  "6": 6,
  septima: 7,
  septimo: 7,
  siete: 7,
