    `<meta property="og:site_name" content="RiffanTV" />`,
    `<meta name="twitter:card" content="${safeImage ? "summary_large_image" : "summary"}" />`,
    `<meta name="twitter:title" content="${safeTitle}" />`,
    `<meta name="twitter:description" content="${safeDesc}" />`
