function classifyAtresCategory(apiCategory, genre, title) {
  const joined = `${apiCategory} ${genre} ${title}`.toLowerCase();
  if (/pasapalabra|ruleta|voz|cara me suena|mask singer|millonario|atrapa|desaf[ií]o|concurso|talent|1%|boom/i.test(
    joined
  )) {
    return "concursos";
  }
  if (/serie|novela|telenovela|ficci[oó]n|libertad|tierras|papel|vis a vis|internado|barco|velvet|quimica|viva|paco|castamar|veneno/i.test(
    joined
  ) || /series|telenovelas/i.test(apiCategory)) {
    return "series";
  }
  if (/investigaci[oó]n|rojo vivo|intermedio|salvados|[eé]vole|xplica|columna|espejo|vale tarde|noticias|debate|documental|reportaje|actualidad|informativo/i.test(
    joined
  )) {
    return "actualidad";
  }
  return "entretenimiento";
}
