function normalizePinturilloGuess(input) {
  return String(input || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();
}
function pinturilloLevenshtein(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  const dp = Array.from({ length: a.length + 1 }, (_, i) => i);
  for (let j = 1; j <= b.length; j += 1) {
    let prev = dp[0];
    dp[0] = j;
    for (let i = 1; i <= a.length; i += 1) {
      const temp = dp[i];
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i] = Math.min(dp[i] + 1, dp[i - 1] + 1, prev + cost);
      prev = temp;
    }
  }
  return dp[a.length];
}
function pickRandomWordChoices(excludeIds = []) {
  const pool = PINTURILLO_WORDS.filter((w) => !excludeIds.includes(w.id));
  const src = pool.length >= 3 ? [...pool] : [...PINTURILLO_WORDS];
  for (let i = src.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [src[i], src[j]] = [src[j], src[i]];
  }
  return src.slice(0, 3);
}
function formatMaskedWord(word, hintIndices) {
  return Array.from(word).map((ch, idx) => {
    if (ch === " ") return "  ";
    if (hintIndices.includes(idx)) return ch.toUpperCase();
    return "_";
  }).join(" ");
}

