function makeCirclePoints(cx, cy, r, steps = 20) {
  const pts = [];
  for (let i = 0; i <= steps; i += 1) {
    const a = i / steps * Math.PI * 2;
    pts.push({
      x: Number((cx + Math.cos(a) * r).toFixed(3)),
      y: Number((cy + Math.sin(a) * r).toFixed(3))
    });
  }
  return pts;
}
