    const senderMeta = clients.get(ws);
    if (!room || !room.headSoccerState || !senderMeta?.userId) return true;
    const isAllowed = room.hostId === senderMeta.userId || room.creatorId === senderMeta.userId || room.headSoccerState.players[0]?.userId === senderMeta.userId;
    if (!isAllowed) return true;
