function getImprovementsSummary() {
  const byPhase = {};
  for (const item of RIFFAN_100_IMPROVEMENTS) {
    byPhase[item.phase] = (byPhase[item.phase] || 0) + 1;
  }
  return {
    total: RIFFAN_100_IMPROVEMENTS.length,
    byPhase,
    items: RIFFAN_100_IMPROVEMENTS
  };
}

// server/services/workerBridge.ts
import fs18 from "fs";
import path15 from "path";
import { fileURLToPath as fileURLToPath2 } from "url";
import { Worker } from "worker_threads";
var __filename2 = fileURLToPath2(import.meta.url);
var __dirname2 = path15.dirname(__filename2);
var BackgroundWorkerBridge = class {
  worker = null;
  heartbeatTimer = null;
  lastPongAt = 0;
  start() {
    if (process.env.NODE_ENV === "test" || this.worker) return;
    const tsPath = path15.resolve(__dirname2, "../workers/backgroundWorker.ts");
    if (!fs18.existsSync(tsPath)) {
      runtimeMetrics.updateWorkerStatus({ mode: "in-process", healthy: true });
      return;
    }
    try {
      const worker = new Worker(tsPath);
      this.worker = worker;
      runtimeMetrics.updateWorkerStatus({ mode: "worker-thread", healthy: true, lastError: null });
      worker.on("message", (msg) => {
        if (msg?.type === "PONG") {
          this.lastPongAt = msg.ts || Date.now();
          runtimeMetrics.updateWorkerStatus({
            mode: "worker-thread",
            healthy: true,
            lastSweepAt: this.lastPongAt
          });
        } else if (msg?.type === "CHECK_HEAD_RESULT") {
          runtimeMetrics.updateWorkerStatus({
            mode: "worker-thread",
            healthy: true,
            lastSweepDurationMs: msg.durationMs || 0,
            lastSweepAt: Date.now()
          });
        }
      });
      worker.on("error", (err) => {
        logger.debug({ err }, "background_worker_fallback_to_in_process");
        runtimeMetrics.updateWorkerStatus({
          mode: "in-process",
          healthy: true,
          lastError: err instanceof Error ? err.message : String(err)
        });
        this.stop();
      });
      worker.on("exit", () => {
        this.worker = null;
      });
      this.heartbeatTimer = setInterval(() => {
        this.worker?.postMessage({ type: "PING" });
      }, 3e4);
      this.heartbeatTimer.unref?.();
      this.worker.postMessage({ type: "PING" });
    } catch (err) {
      logger.debug({ err }, "worker_thread_spawn_skipped_using_in_process");
      runtimeMetrics.updateWorkerStatus({ mode: "in-process", healthy: true });
    }
  }
  recordSweepCycle(durationMs) {
    const snap = runtimeMetrics.getSnapshot();
    runtimeMetrics.updateWorkerStatus({
      sweepsCompleted: snap.worker.sweepsCompleted + 1,
      lastSweepDurationMs: Math.round(durationMs),
      lastSweepAt: Date.now(),
      healthy: true
    });
  }
  stop() {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
    if (this.worker) {
      void this.worker.terminate().catch(() => {
      });
      this.worker = null;
    }
  }
};
var workerBridge = new BackgroundWorkerBridge();

